"use client";

import Image from "next/image";
import { useCallback, useEffect, useRef, useState } from "react";

const posts = [
  { src: "/images/real-community.webp", alt: "Neighbors gathering at the Sweets & Sourdough cart", position: "50% 50%" },
  { src: "/images/real-sourdough.webp", alt: "Fresh Sweets & Sourdough loaf", position: "50% 50%" },
  { src: "/images/real-packaging.webp", alt: "Branded biscuit bags at the cart", position: "50% 54%" },
  { src: "/images/real-rolls.webp", alt: "Sourdough cinnamon rolls", position: "50% 56%" },
  { src: "/images/real-story.webp", alt: "Heather greeting a customer", position: "40% 50%" },
  { src: "/images/real-cart.webp", alt: "The stocked roadside bakery cart", position: "50% 50%" },
  { src: "/images/real-biscuits.webp", alt: "Jalapeño cheddar sourdough biscuits", position: "50% 64%" },
  { src: "/images/real-coffee.webp", alt: "Complimentary coffee at the cart", position: "50% 48%" },
  { src: "/images/real-sign.webp", alt: "Hand-painted bakery cart sign", position: "55% 50%" },
];

export default function GalleryCarousel() {
  const rail = useRef<HTMLDivElement>(null);
  const [paused, setPaused] = useState(false);
  const loopPosts = [...posts, ...posts];

  const move = useCallback((direction: 1 | -1) => {
    const el = rail.current;
    const first = el?.firstElementChild as HTMLElement | null;
    if (!el || !first) return;

    const gap = parseFloat(getComputedStyle(el).columnGap || "0");
    const step = first.offsetWidth + gap;
    const cycleWidth = step * posts.length;

    if (direction === -1 && el.scrollLeft < step * 0.5) {
      el.scrollLeft = cycleWidth;
    }

    el.scrollBy({ left: step * direction, behavior: "smooth" });

    window.setTimeout(() => {
      if (direction === 1 && el.scrollLeft >= cycleWidth - step * 0.35) {
        el.scrollLeft -= cycleWidth;
      }
    }, 650);
  }, []);

  useEffect(() => {
    if (paused || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const timer = window.setInterval(() => move(1), 3800);
    return () => window.clearInterval(timer);
  }, [move, paused]);

  return (
    <div
      className="social-carousel"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
    >
      <div className="social-rail" ref={rail}>
        {loopPosts.map((post, index) => (
          <a
            className="social-post image-wrap"
            href="https://instagram.com/sweetestsourdoughstl"
            target="_blank"
            rel="noreferrer"
            aria-label={`View Sweets & Sourdough on Instagram: ${post.alt}`}
            key={`${post.src}-${index}`}
          >
            <Image
              src={post.src}
              alt={post.alt}
              fill
              quality={90}
              sizes="(max-width: 759px) 62vw, 22vw"
              style={{ objectPosition: post.position }}
            />
          </a>
        ))}
      </div>
      <div className="carousel-controls">
        <button type="button" onClick={() => move(-1)} aria-label="Previous Instagram photos">‹</button>
        <span>Swipe the weekend</span>
        <button type="button" onClick={() => move(1)} aria-label="Next Instagram photos">›</button>
      </div>
    </div>
  );
}
